    integer errors = 0;
    integer i;

    initial begin
        clk = 0;
        reset = 0;

        // 1. Test synchronous reset behavior
        @(posedge clk);
        reset = 1;
        #1;
        if (q !== 4'b0001) begin
            $display("ERROR: Reset failed to set q to 1. Got %b", q);
            errors = errors + 1;
        end

        // Release reset
        @(posedge clk);
        reset = 0;
        #1;
        if (q !== 4'b0001) begin
            $display("ERROR: Releasing reset changed q incorrectly. Got %b", q);
            errors = errors + 1;
        end

        // 2. Test full sequence counting from 1 to 10 and wrapping back to 1
        // Expected sequence after reset (q starts at 1, increments each cycle):
        // Cycle 0 (after reset release): q = 1
        // Cycle 1: q = 2
        // Cycle 2: q = 3
        // Cycle 3: q = 4
        // Cycle 4: q = 5
        // Cycle 5: q = 6
        // Cycle 6: q = 7
        // Cycle 7: q = 8
        // Cycle 8: q = 9
        // Cycle 9: q = 10 (4'b1010)
        // Cycle 10: q wraps to 1 (4'b0001)

        for (i = 1; i <= 10; i = i + 1) begin
            @(posedge clk);
            #1; // Wait for non-blocking assignment
        end

        // After 10 clock cycles from q=1, it should have reached 10 and wrapped back to 1
        if (q !== 4'b0001) begin
            $display("ERROR: Decade counter did not wrap correctly from 10 to 1. Got %b (expected 0001)", q);
            errors = errors + 1;
        end

        // 3. Test asynchronous/illegal state recovery (e.g., if q somehow becomes 0 or >10)
        // Since we cannot directly force internal regs easily without hierarchical paths,
        // we test assert-reset mid-count to check robustness.
        @(posedge clk);
        reset = 1;
        #1;
        if (q !== 4'b0001) begin
            $display("ERROR: Mid-count synchronous reset failed. Got %b", q);
            errors = errors + 1;
        end

        @(posedge clk);
        reset = 0;

        // Final result reporting
        if (errors === 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
